package vn.somehouse;
import static vn.somehouse.ApiTypes.*;import com.fasterxml.jackson.databind.*;import org.jsoup.Jsoup;import org.jsoup.safety.Safelist;import org.springframework.jdbc.core.*;import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Service;import java.sql.*;import java.math.BigDecimal;import java.text.Normalizer;import java.time.*;import java.util.*;
@Service public class CatalogService {
 final JdbcTemplate db;final NamedParameterJdbcTemplate sql;final ObjectMapper json;
 static final Set<String>KINDS=Set.of("PROPERTY","PROJECT","ARTICLE","PAGE"),TYPES=Set.of("APARTMENT","CONDOTEL","HOUSE","VILLA","LAND","SHOPHOUSE","OFFICETEL","PENTHOUSE","DUPLEX");
 static final Safelist HTML=Safelist.relaxed().addTags("div","span","section","main","article","figure","figcaption").addAttributes(":all","class","id").addAttributes("img","loading","width","height").addProtocols("a","href","tel","mailto").addEnforcedAttribute("a","rel","noopener noreferrer").preserveRelativeLinks(true);
 CatalogService(JdbcTemplate d,ObjectMapper j){db=d;sql=new NamedParameterJdbcTemplate(d);json=j;}
 static String str(String s){return s==null?"":s;}static String normal(String s){return Normalizer.normalize(str(s).replace('đ','d').replace('Đ','D'),Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);}
 static String locale(String s){if(s==null||s.isBlank())return "vi";if(!Set.of("vi","en","ru").contains(s))throw ApiException.invalid("Ngôn ngữ không hợp lệ.");return s;}
 static String safeHtml(String s){return Jsoup.clean(str(s),"https://somehouse.invalid",HTML);}static void asset(String u){if(u==null||u.length()>1000||(!u.isEmpty()&&!u.startsWith("/")&&!u.startsWith("https://"))||u.startsWith("//")||u.contains("\\")||u.contains(".."))throw ApiException.invalid("Đường dẫn ảnh không hợp lệ.");}
 JsonNode read(String s){try{return json.readTree(s);}catch(Exception e){throw new IllegalStateException("Stored JSON invalid",e);}}String write(JsonNode n){try{return json.writeValueAsString(n==null?json.createObjectNode():n);}catch(Exception e){throw ApiException.invalid("JSON không hợp lệ.");}}
 static int integer(Map<String,String> p,String k,int fallback,int min,int max){String s=p.get(k);int n=s==null||s.isBlank()?fallback:Integer.parseInt(s);if(n<min||n>max)throw ApiException.invalid("Tham số "+k+" ngoài phạm vi.");return n;}
 Item map(ResultSet r,int row)throws SQLException{return new Item(r.getLong("id"),r.getString("kind"),r.getString("slug"),r.getString("title"),r.getString("summary"),r.getString("body"),r.getString("cover_url"),r.getString("transaction_type"),r.getString("property_type"),r.getString("project_slug"),r.getBigDecimal("price"),r.getBigDecimal("area"),r.getInt("bedrooms"),r.getString("city"),r.getString("direction"),r.getString("furniture"),r.getString("legal_status"),r.getString("position"),read(r.getString("data_json")),r.getLong("version"),r.getObject("published_at",LocalDateTime.class));}
 String columns(String l,boolean body){return "i.id,i.kind,i.slug,COALESCE(NULLIF(i.title_"+l+",N''),i.title_vi) AS title,COALESCE(NULLIF(i.summary_"+l+",N''),i.summary_vi) AS summary,"+(body?"COALESCE(NULLIF(i.body_"+l+",N''),i.body_vi)":"CAST(N'' AS NVARCHAR(MAX))")+" AS body,i.cover_url,i.transaction_type,i.property_type,p.slug AS project_slug,i.price,i.area,i.bedrooms,i.city,i.direction,i.furniture,i.legal_status,i.position,i.data_json,i.version,i.published_at";}
 public Page<Item> list(String kind,Map<String,String> q,boolean admin){if(!KINDS.contains(kind))throw ApiException.invalid("Loại nội dung không hợp lệ.");String lang=locale(q.get("locale"));int page=integer(q,"page",0,0,100000),size=integer(q,"size",12,1,50);var p=new MapSqlParameterSource().addValue("kind",kind,Types.VARCHAR);var w=new StringBuilder("i.kind=:kind");if(!admin)w.append(" AND i.published=1");String search=str(q.get("q")).trim();if(search.length()>200)throw ApiException.invalid("Từ khóa quá dài.");if(!search.isEmpty()){w.append(" AND i.search_text LIKE :q ESCAPE '~'");p.addValue("q","%"+normal(search).replace("~","~~").replace("%","~%").replace("_","~_").replace("[","~[")+"%");}
  for(var f:Map.of("type","i.transaction_type","propertyType","i.property_type","project","p.slug","city","i.city","direction","i.direction","furniture","i.furniture","legalStatus","i.legal_status","position","i.position").entrySet())if(q.containsKey(f.getKey())&&!q.get(f.getKey()).isBlank()){w.append(" AND "+f.getValue()+"=:"+f.getKey());p.addValue(f.getKey(),q.get(f.getKey()));}
  for(String f:List.of("minPrice","maxPrice","minArea","maxArea"))if(q.containsKey(f)&&!q.get(f).isBlank()){BigDecimal v=new BigDecimal(q.get(f));if(v.signum()<0)throw ApiException.invalid("Giá trị không được âm.");w.append(" AND i."+(f.endsWith("Price")?"price":"area")+(f.startsWith("min")?">=":"<=")+":"+f);p.addValue(f,v);}
  if(q.containsKey("bedrooms")&&!q.get("bedrooms").isBlank()){w.append(" AND i.bedrooms=:beds");p.addValue("beds",integer(q,"bedrooms",0,0,100));}
  String order=switch(str(q.get("sort"))){case "","recent"->"i.published_at DESC,i.id DESC";case "price_asc"->"i.price ASC,i.id DESC";case "price_desc"->"i.price DESC,i.id DESC";case "area_desc"->"i.area DESC,i.id DESC";default->throw ApiException.invalid("Kiểu sắp xếp không hợp lệ.");};String from=" FROM catalog_items i LEFT JOIN catalog_items p ON p.id=i.project_id WHERE "+w;long total=Objects.requireNonNull(sql.queryForObject("SELECT COUNT_BIG(*)"+from,p,Long.class));p.addValue("offset",page*size);p.addValue("size",size);return new Page<>(sql.query("SELECT "+columns(lang,false)+from+" ORDER BY "+order+" OFFSET :offset ROWS FETCH NEXT :size ROWS ONLY",p,this::map),page,size,total,(int)Math.ceil((double)total/size));}
 public Item detail(String kind,String slug,String l){String lang=locale(l);var rows=sql.query("SELECT "+columns(lang,true)+" FROM catalog_items i LEFT JOIN catalog_items p ON p.id=i.project_id WHERE i.kind=:kind AND i.slug=:slug AND i.published=1",Map.of("kind",kind,"slug",slug),this::map);if(rows.isEmpty())throw ApiException.missing();return rows.getFirst();}
 Map<String,Object> fields(ItemInput i){if(!KINDS.contains(i.kind()))throw ApiException.invalid("Loại nội dung không hợp lệ.");if(i.kind().equals("PROPERTY")&&(i.transactionType()==null||!TYPES.contains(str(i.propertyType()))))throw ApiException.invalid("Cần loại giao dịch và loại hình hợp lệ.");asset(i.coverUrl());if(i.data()!=null&&!i.data().isObject())throw ApiException.invalid("Thuộc tính bổ sung phải là JSON object.");String data=write(i.data());if(data.length()>64000)throw ApiException.invalid("Dữ liệu ảnh quá lớn.");if(i.data()!=null)for(String k:List.of("gallery","thumbnails")){var a=i.data().get(k);if(a!=null){if(!a.isArray()||a.size()>60)throw ApiException.invalid("Danh sách ảnh không hợp lệ.");for(var u:a){if(!u.isTextual())throw ApiException.invalid("Ảnh không hợp lệ.");asset(u.asText());}}}
  Long project=null;if(i.projectSlug()!=null&&!i.projectSlug().isBlank()){var ids=db.queryForList("SELECT id FROM catalog_items WHERE kind='PROJECT' AND slug=?",Long.class,i.projectSlug());if(ids.isEmpty())throw ApiException.invalid("Dự án chưa tồn tại.");project=ids.getFirst();}var f=new LinkedHashMap<String,Object>();f.put("kind",i.kind());f.put("slug",i.slug());f.put("title_vi",i.titleVi());f.put("title_en",i.titleEn()==null||i.titleEn().isBlank()?i.titleVi():i.titleEn());f.put("title_ru",i.titleRu()==null||i.titleRu().isBlank()?i.titleVi():i.titleRu());f.put("summary_vi",str(i.summaryVi()));f.put("summary_en",str(i.summaryEn()));f.put("summary_ru",str(i.summaryRu()));f.put("body_vi",safeHtml(i.bodyVi()));f.put("body_en",safeHtml(i.bodyEn()));f.put("body_ru",safeHtml(i.bodyRu()));f.put("cover_url",i.coverUrl());f.put("transaction_type",i.transactionType());f.put("property_type",i.propertyType());f.put("project_id",project);f.put("price",i.price());f.put("area",i.area());f.put("bedrooms",i.bedrooms());f.put("city",str(i.city()));f.put("direction",str(i.direction()));f.put("furniture",str(i.furniture()));f.put("legal_status",str(i.legalStatus()));f.put("position",str(i.position()));String search=normal(i.titleVi()+" "+i.titleEn()+" "+i.titleRu()+" "+i.city()+" "+i.projectSlug());f.put("search_text",search.substring(0,Math.min(2000,search.length())));f.put("data_json",data);f.put("published",i.published());f.put("published_at",Timestamp.valueOf(i.publishedAt()==null?LocalDateTime.now(Clock.systemUTC()):i.publishedAt()));return f;}
 MapSqlParameterSource params(Map<String,Object> f){var p=new MapSqlParameterSource();f.forEach((k,v)->p.addValue(k,v,v instanceof String?Types.NVARCHAR:v instanceof BigDecimal?Types.DECIMAL:v instanceof Boolean?Types.BIT:v instanceof Timestamp?Types.TIMESTAMP:v instanceof Integer?Types.INTEGER:Types.BIGINT));return p;}
 public long create(ItemInput i){var f=fields(i);return Objects.requireNonNull(sql.queryForObject("INSERT INTO catalog_items("+String.join(",",f.keySet())+") OUTPUT INSERTED.id VALUES("+String.join(",",f.keySet().stream().map(k->":"+k).toList())+")",params(f),Long.class));}
 boolean exists(long id){return Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM catalog_items WHERE id=?",Integer.class,id))>0;}
 public void update(long id,ItemInput i){var f=fields(i);int n=sql.update("UPDATE catalog_items SET "+String.join(",",f.keySet().stream().map(k->k+"=:"+k).toList())+",version=version+1,updated_at=SYSUTCDATETIME() WHERE id=:id AND version=:version AND kind=:kind",params(f).addValue("id",id).addValue("version",i.version()));if(n==0){if(!exists(id))throw ApiException.missing();throw ApiException.conflict();}}
 public void delete(long id,long version){if(db.update("DELETE FROM catalog_items WHERE id=? AND version=?",id,version)==0){if(!exists(id))throw ApiException.missing();throw ApiException.conflict();}}
 public Map<String,Object> editor(long id){var rows=db.queryForList("SELECT i.*,p.slug AS project_slug FROM catalog_items i LEFT JOIN catalog_items p ON p.id=i.project_id WHERE i.id=?",id);if(rows.isEmpty())throw ApiException.missing();var row=rows.getFirst();var out=new LinkedHashMap<String,Object>();for(String f:List.of("kind","slug","title_vi","title_en","title_ru","summary_vi","summary_en","summary_ru","body_vi","body_en","body_ru","cover_url","transaction_type","property_type","project_slug","price","area","bedrooms","city","direction","furniture","legal_status","position","published","version","published_at")){String[] a=f.split("_");String camel=a[0];for(int n=1;n<a.length;n++)camel+=a[n].substring(0,1).toUpperCase()+a[n].substring(1);Object v=row.get(f);if(v instanceof Timestamp t)v=t.toLocalDateTime();out.put(camel,v);}out.put("data",read((String)row.get("data_json")));out.put("id",id);return out;}
}
